from pathlib import Path
import json,hashlib,cadquery as cq
O=Path(__file__).resolve().parent;I=json.loads((O/'board-inventory.json').read_text());p=next(x for x in I['parts'] if x['ref']=='U10');assert p['side']=='B' and p['rotation_deg']==0
pads={x['number']:x['position_mm'] for x in p['pads']};assert abs(pads['A2'][0]-pads['A1'][0]-.4)<1e-6;assert abs(pads['B1'][1]-pads['A1'][1]+.4)<1e-6
s=cq.importers.importStep(str(O/'u10-yfp0004-envelope.step')).val().rotate((0,0,0),(1,0,0),180).translate((p['position_mm'][0],-p['position_mm'][1],0));f=O/'u10-envelope-positioned-study.step';cq.exporters.export(s,str(f));c=cq.importers.importStep(str(f)).val();assert c.isValid();b=c.BoundingBox();assert abs(b.zmin+.5)<1e-6 and abs(b.zmax)<1e-6
r={'status':'POSITIONED_ENVELOPE_NOT_COMPLETE_ASSEMBLY','pcb_sha256':I['pcb_sha256'],'file':f.name,'sha256':hashlib.sha256(f.read_bytes()).hexdigest(),'axis_evidence':'A1->A2 follows PCB +X; A1->B1 follows PCB -Y; symmetric square envelope. Bottom mounted, body extends toward negative STEP Z.','bounds_mm':[b.xmin,b.xmax,b.ymin,b.ymax,b.zmin,b.zmax],'solder_standoff_mm':0,'limitations':['Zero solder standoff is visualization datum only.','Cuboid includes maximum total height from ball seating plane; no detailed balls.','Not combined with complete assembly; no enclosure fit approval.']};(O/'u10-position-review.json').write_text(json.dumps(r,indent=2)+'\n');print(r['bounds_mm'])
